window.docContents[201].resolve({"/#Cvc___lean----High-Level-CVC5-API":{"contents":"Cvc.lean is a high-level Lean 4 API for the cvc5 SMT solver, built on top of the\nlean-cvc5 Lean library. It adds a lot of quality of life features and strives to\nprovide strong static guarantees. The following section of this manual present the library in\ndetails.\n\n\n\n\n\n\n\n\n\n\n\n","context":"","header":"Cvc.lean -- High-Level CVC5 API","id":"/#Cvc___lean----High-Level-CVC5-API"}});